package com.agencytrip.agencytripapi.infrastructure.adapter.in.web;
import com.agencytrip.agencytripapi.application.dto.Requests; import com.agencytrip.agencytripapi.application.service.CatalogService; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController public class CatalogController {private final CatalogService s;public CatalogController(CatalogService s){this.s=s;}
 @GetMapping("/api/Destinos") public Object destinations(){return s.destinations();}@PostMapping("/api/Destinos")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object createDestination(@Valid@RequestBody Requests.Destination r){return Map.of("mensaje","Destino creado correctamente.","destino",s.createDestination(r));}@PutMapping("/api/Destinos/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object updateDestination(@PathVariable int id,@Valid@RequestBody Requests.Destination r){return Map.of("mensaje","Destino actualizado correctamente.","destino",s.updateDestination(id,r));}@DeleteMapping("/api/Destinos/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object disableDestination(@PathVariable int id){s.disableDestination(id);return Map.of("mensaje","Destino desactivado correctamente.");}
 @GetMapping("/api/Hoteles")public Object hotels(){return s.hotels();}@PostMapping("/api/Hoteles")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object createHotel(@Valid@RequestBody Requests.Hotel r){return Map.of("mensaje","Hotel creado correctamente.","hotel",s.createHotel(r));}@PutMapping("/api/Hoteles/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object updateHotel(@PathVariable int id,@Valid@RequestBody Requests.Hotel r){return Map.of("mensaje","Hotel actualizado correctamente.","hotel",s.updateHotel(id,r));}@DeleteMapping("/api/Hoteles/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object disableHotel(@PathVariable int id){s.disableHotel(id);return Map.of("mensaje","Hotel desactivado correctamente.");}
 @GetMapping("/api/Transportes")public Object transports(){return s.transports();}@PostMapping("/api/Transportes")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object createTransport(@Valid@RequestBody Requests.Transport r){return Map.of("mensaje","Transporte creado correctamente.","transporte",s.createTransport(r));}@PutMapping("/api/Transportes/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object updateTransport(@PathVariable int id,@Valid@RequestBody Requests.Transport r){return Map.of("mensaje","Transporte actualizado correctamente.","transporte",s.updateTransport(id,r));}@DeleteMapping("/api/Transportes/{id}")@PreAuthorize("hasRole('ADMINISTRADOR')")public Object disableTransport(@PathVariable int id){s.disableTransport(id);return Map.of("mensaje","Transporte desactivado correctamente.");}}
